select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'ece:official:equipment:es:c6a9b98b612f27c0d1503b17' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c6a9b98b612f27c0d1503b17' and payload#>'{features}'=$verify_4e1d536c18987fb6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Si la piedra está tocando el suelo, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de tierra, como si hubieras lanzado conjurar elemental. La piedra no puede volver a emplearse de esta manera hasta el siguiente amanecer. La piedra pesa 2,5 kg.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4e1d536c18987fb6$::jsonb and revision=3) union all select 'ece:official:equipment:es:c7bd474b6e2f8bc12a428038' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c7bd474b6e2f8bc12a428038' and payload#>'{features}'=$verify_18e6126021f5b235$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a una criatura con esta arma mágica y saques un 20 en la tirada de ataque, el objetivo sufrirá 3d6 de daño necrótico adicional si no es un autómata o un muerto viviente. Además, obtendrás una cantidad de puntos de golpe temporales igual al daño adicional infligido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_18e6126021f5b235$::jsonb and revision=3) union all select 'ece:official:equipment:es:c7cb954c8d7ea77c90cdd4cb' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c7cb954c8d7ea77c90cdd4cb' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_ff84cbbf5081858d$[{"id":"official-base-table","rows":[["Garrote","1 pp","2 lb","1d4 contundente","+0","Ligera"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_ff84cbbf5081858d$::jsonb and revision=3) union all select 'ece:official:equipment:es:c854a59e028f50e24ed1d734' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c854a59e028f50e24ed1d734' and payload#>'{features}'=$verify_6fb68522b9bd82ca$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, el terreno difícil no te costará movimiento adicional. Además, la magia no podrá reducir tu velocidad ni dejarte apresado o paralizado.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6fb68522b9bd82ca$::jsonb and revision=3) union all select 'ece:official:equipment:es:cad362e9a0790605f65af7ae' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cad362e9a0790605f65af7ae' and payload#>'{features}'=$verify_e1efd99463b4d636$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, mientras tengas sintonización con ella, tus puntos de golpe máximos aumentan en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta hacha está maldita y, al sintonizarte con ella, te afectará la maldición. Mientras sufras la maldición, no querrás deshacerte voluntariamente del hacha y la mantendrás siempre a tu alcance. También tendrás desventaja en las tiradas de ataque con otras armas, a menos que no haya ningún enemigo que puedas ver u oír a 18 m o menos de ti.\n\nCuando una criatura hostil te haga daño, si tienes el hacha en tu posesión, deberás superar una tirada de salvación de Sabiduría con CD 15 o sucumbirás a una furia berserk. Mientras estés bajo sus efectos, deberás utilizar tu acción cada asalto para atacar a la criatura que tengas más cerca con el hacha. Si puedes realizar ataques adicionales como parte de la acción de atacar, los utilizarás para atacar a la siguiente criatura más próxima tras derrotar a tu objetivo actual. Si tienes varios objetivos posibles, atacarás a uno al azar. Seguirás en ese estado hasta que comiences tu turno y no haya criaturas que puedas ver u oír a 18 m o menos de ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1efd99463b4d636$::jsonb and payload#>'{rules,personalDescription}'=$verify_a5d59301b3113214$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Además, mientras estés en sintonía con esta arma, tu máximo de puntos de vida aumenta en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta arma está maldita, y al acostumbrarte a ella, la maldición se extiende a ti. Mientras permanezcas maldito, no estarás dispuesto a desprenderte de ella, manteniéndola a tu alcance en todo momento. También tienes Desventaja en las tiradas de ataque con armas distintas a esta. Siempre que otra criatura te dañe mientras el arma esté en tu posesión, debes superar una tirada de salvación de Sabiduría CD 15 o entrarás en estado de rabieta. Este estado de rabieta termina cuando comienzas tu turno y no hay criaturas a 60 pies o menos de ti que puedas ver u oír. Mientras estás en estado de rabieta, consideras a la criatura más cercana a ti que puedas ver u oír como tu enemiga. Si hay varias criaturas posibles, elige una al azar. En cada uno de tus turnos, debes acercarte lo más posible a la criatura y realizar la acción de Ataque, apuntando a la criatura. Si no puedes acercarte lo suficiente a la criatura para atacarla con el arma, tu turno termina después de haber usado todo tu movimiento disponible. Si la criatura muere o ya no puedes verla ni oírla, la siguiente criatura más cercana que puedas ver u oír se convierte en tu nuevo objetivo."$verify_a5d59301b3113214$::jsonb and revision=3) union all select 'ece:official:equipment:es:cb06ceb25f2b8c9a2ef8e087' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb06ceb25f2b8c9a2ef8e087' and payload#>'{features}'=$verify_f05deeaf62894d19$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este frasco de cristal, de 7,5 cm de diámetro, contiene 1d4 + 1 dosis de una mezcla espesa que huele ligeramente a aloe. El frasco y su contenido pesan 250 g.\n\nComo acción, una dosis del ungüento puede tragarse o aplicarse en la piel. La criatura que la reciba recuperará 2d8 + 2 puntos de golpe, dejará de estar envenenada y se curará de cualquier enfermedad.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f05deeaf62894d19$::jsonb and revision=3) union all select 'ece:official:equipment:es:cb25f6558815b4e93185bb43' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb25f6558815b4e93185bb43' and payload#>'{description}'=$verify_e6013f2a47c339f3$"Objeto · Precio base · Peso\nPluma (para escribir) · 2 pc · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_e6013f2a47c339f3$::jsonb and payload#>'{rules,definition,description}'=$verify_d81ecc59fcab73d4$[{"id":"official-table","rows":[["Pluma (para escribir)","2 pc","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_d81ecc59fcab73d4$::jsonb and revision=3) union all select 'ece:official:equipment:es:cb90976a4748db28834a8e62' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb90976a4748db28834a8e62' and payload#>'{description}'=$verify_f6dd41d6d6cb54a8$"Objeto · Precio base · Peso\nHerramientas de herrero · 20 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f6dd41d6d6cb54a8$::jsonb and payload#>'{features}'=$verify_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_2b2bca0e5c7a5789$::jsonb and payload#>'{rules,definition,description}'=$verify_fffb5f0692bd7e5b$[{"id":"official-table","rows":[["Herramientas de herrero","20 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_fffb5f0692bd7e5b$::jsonb and revision=4) union all select 'ece:official:equipment:es:cbfbeb4aafdeb42aa1660850' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cbfbeb4aafdeb42aa1660850' and payload#>'{features}'=$verify_cb1746b6035208e3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +3 a las tiradas de ataque y de daño realizadas con él.\n\nEl bastón tiene 10 cargas. Cuando impactes con un ataque cuerpo a cuerpo con él, podrás gastar hasta 3 cargas. Por cada carga empleada, el objetivo recibirá 1d6 de daño de fuerza adicional. El bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_cb1746b6035208e3$::jsonb and payload#>'{rules,personalDescription}'=$verify_4a5034accb59b926$"Este bastón se puede utilizar como un bastón mágico que otorga una bonificación de +3 a las tiradas de ataque y daño realizadas con él. El bastón tiene 10 cargas. Cuando impactas con un ataque cuerpo a cuerpo usándolo, puedes gastar hasta 3 cargas. Por cada carga que gastes, el objetivo sufre 1d6 de daño de Fuerza adicional.\n\nRecuperación de cargas. El bastón recupera 1d6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira 1d20. Con un 1, el bastón se convierte en un bastón no mágico."$verify_4a5034accb59b926$::jsonb and revision=3) union all select 'ece:official:equipment:es:cc6d904679038c3cb3a54a64' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cc6d904679038c3cb3a54a64' and payload#>'{features}'=$verify_db5c645ac61c50c7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras sostengas este abanico, podrás utilizar una acción para lanzar ráfaga de viento (CD de salvación 13) desde él. Una vez utilizado, no debería volver a emplearse hasta el siguiente amanecer. Cada vez que se vuelva a utilizar hasta ese momento, habrá una probabilidad acumulativa del 20 % de que no funcione y se haga jirones inútiles y no mágicos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_db5c645ac61c50c7$::jsonb and revision=3) union all select 'ece:official:equipment:es:cd01816f1e2741e749410128' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cd01816f1e2741e749410128' and payload#>'{features}'=$verify_6370f594d411e3b1$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Debes ser competente con instrumentos de viento para poder tocar esta flauta. Mientras tengas sinto- nización con ella, las ratas normales y las ratas gigantes serán indiferentes hacia ti y no te atacarán salvo que las amenaces o dañes.\n\nLa flauta tiene 3 cargas. Si utilizas una acción para tocarla, podrás utilizar una acción adicional y gastar de 1 a 3 cargas para convocar un enjambre de ratas con cada carga empleada, siempre y cuando haya suficientes ratas a 0,75 km o menos de ti para que las convoques de esta manera (según decida tu GM). Si no hay ratas suficientes para formar un enjambre, la carga se desperdiciará. Los enjambres convocados irán hacia la música por el camino más corto disponible, pero, por lo demás, no estarán bajo tu control. La flauta recupera 1d3 cargas empleadas cada día, al amanecer.\n\nCuando un enjambre de ratas que no esté bajo el control de otra criatura se acerque a 9 m o menos de ti mientras estés tocando la flauta, podrás realizar una prueba de Carisma contra una prueba de Sabiduría del enjambre. Si pierdes, el enjambre se comportará de forma normal y no caerá bajo el influjo de la música de la flauta durante las siguientes 24 horas. Si ganas, el enjambre caerá bajo el influjo de la música de la flauta y se volverá amistoso hacia tus compañeros y tú mientras sigas tocando la flauta cada asalto como acción. Un enjambre amistoso obedece tus órdenes. Si no le das ninguna orden a un enjambre amistoso, se defenderá, pero no realizará ninguna otra acción. Si un enjambre amistoso comienza su turno y no puede escuchar la música de la flauta, se acabará tu control sobre el enjambre, este se comportará de forma normal y no podrá caer bajo el influjo de la música de la flauta durante las siguientes 24 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6370f594d411e3b1$::jsonb and payload#>'{rules,personalDescription}'=$verify_ed5cf4de1325424e$"Debes ser competente con instrumentos de viento para poder usar esta Aauta. Mientras estés sintonizado con ella, las ratas ordinarias y gigantes se mostrarán indiferentes hacia ti, y no te atacarán a menos que las dañes o amenaces.\n\nLa Aauta tiene 3 cargas. Si empleas una acción para tocar la Aauta, puedes además utilizar una acción adicional para gastar de l a 3 cargas, convocando a un enjambre de ratas (ver perfil en el Monster Manual) por cada carga usada, suponiendo que haya suficientes ratas a media milla de ti como para ser convocadas de esta manera. Si no hay suficientes ratas para formar un enjambre, la carga se desperdicia. Los enjambres convocados se desplazan hacia la música por el camino más corto, pero por lo demás no están bajo tu control. La Aauta recupera ld3 cargas empleadas cada día, al amanecer.\n\nCuando un enjambre de ratas que no esté bajo el con trol de otra criatura se acerque a 30 pies o menos de ti mientras tocas la Aauta, puedes hacer una tirada enfrentada de Carisma contra la Sabiduría del enjambre. Si fallas esta tirada, el enjambre se comporta de forma normal y no puede ser influido por la música de la Aauta en las próximas 24 horas. Si la superas, el enjambre se ve influenciado por la música de la Aauta y se vuelve amistoso hacia ti y tus compañeros mientras sigas tocando la Aauta cada asalto, utilizando una acción para ello. Un enjambre amistoso obedece tus órdenes. Si no les das ninguna, se defenderá de criaturas hostiles, pero no realizará ninguna otra acción. Si un enjambre amistoso no puede oír la música de la flauta al principio de su turno, perderás el control sobre él, pasará a comportarse normalmente y no podrá ser influenciado de nuevo de esta manera durante 24 horas."$verify_ed5cf4de1325424e$::jsonb and revision=3) union all select 'ece:official:equipment:es:ce1d5cf7c2597a556c05a8f1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ce1d5cf7c2597a556c05a8f1' and payload#>'{features}'=$verify_e1efd99463b4d636$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, mientras tengas sintonización con ella, tus puntos de golpe máximos aumentan en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta hacha está maldita y, al sintonizarte con ella, te afectará la maldición. Mientras sufras la maldición, no querrás deshacerte voluntariamente del hacha y la mantendrás siempre a tu alcance. También tendrás desventaja en las tiradas de ataque con otras armas, a menos que no haya ningún enemigo que puedas ver u oír a 18 m o menos de ti.\n\nCuando una criatura hostil te haga daño, si tienes el hacha en tu posesión, deberás superar una tirada de salvación de Sabiduría con CD 15 o sucumbirás a una furia berserk. Mientras estés bajo sus efectos, deberás utilizar tu acción cada asalto para atacar a la criatura que tengas más cerca con el hacha. Si puedes realizar ataques adicionales como parte de la acción de atacar, los utilizarás para atacar a la siguiente criatura más próxima tras derrotar a tu objetivo actual. Si tienes varios objetivos posibles, atacarás a uno al azar. Seguirás en ese estado hasta que comiences tu turno y no haya criaturas que puedas ver u oír a 18 m o menos de ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1efd99463b4d636$::jsonb and payload#>'{rules,personalDescription}'=$verify_a5d59301b3113214$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Además, mientras estés en sintonía con esta arma, tu máximo de puntos de vida aumenta en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta arma está maldita, y al acostumbrarte a ella, la maldición se extiende a ti. Mientras permanezcas maldito, no estarás dispuesto a desprenderte de ella, manteniéndola a tu alcance en todo momento. También tienes Desventaja en las tiradas de ataque con armas distintas a esta. Siempre que otra criatura te dañe mientras el arma esté en tu posesión, debes superar una tirada de salvación de Sabiduría CD 15 o entrarás en estado de rabieta. Este estado de rabieta termina cuando comienzas tu turno y no hay criaturas a 60 pies o menos de ti que puedas ver u oír. Mientras estás en estado de rabieta, consideras a la criatura más cercana a ti que puedas ver u oír como tu enemiga. Si hay varias criaturas posibles, elige una al azar. En cada uno de tus turnos, debes acercarte lo más posible a la criatura y realizar la acción de Ataque, apuntando a la criatura. Si no puedes acercarte lo suficiente a la criatura para atacarla con el arma, tu turno termina después de haber usado todo tu movimiento disponible. Si la criatura muere o ya no puedes verla ni oírla, la siguiente criatura más cercana que puedas ver u oír se convierte en tu nuevo objetivo."$verify_a5d59301b3113214$::jsonb and revision=3) union all select 'ece:official:equipment:es:cf69ef489f5705da5fee89ad' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cf69ef489f5705da5fee89ad' and payload#>'{features}'=$verify_c875a6812fbbc44a$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, tendrás resistencia al daño de fuego.\n\nEl bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: bola de fuego (3 cargas), manos ardientes (1 carga), muro de fuego (4 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se ennegrece, se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_c875a6812fbbc44a$::jsonb and revision=3) union all select 'ece:official:equipment:es:cf92c104e190056bf85689b9' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cf92c104e190056bf85689b9' and payload#>'{features}'=$verify_9b1069889606242f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Debes ser competente con instrumentos de viento para poder tocar esta flauta. Tiene 3 cargas. Puedes utilizar una acción para tocarla y gastar 1 carga para crear una melodía inquietante a la vez que fascinante. Todas las criaturas que estén a 9 m o menos de ti y te escuchen tocar deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Si lo deseas, todas las criaturas situadas en esa zona que no sean hostiles hacia a ti superarán automáticamente la tirada de salvación. Las criaturas que fallen la tirada de salvación podrán repetirla al final de cada uno de sus turnos y, si la superan, se librarán del efecto. Las criaturas que superen la tirada de salvación serán inmunes al efecto de esta flauta durante 24 horas. La flauta recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9b1069889606242f$::jsonb and revision=3) union all select 'ece:official:equipment:es:cfdfaf1c30544aca1b7b1c6b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cfdfaf1c30544aca1b7b1c6b' and payload#>'{features}'=$verify_1be94401f6a37d1a$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nConsciencia (rara). No puedes ser sorprendido mientras este romboide azul oscuro gire alrededor de tu cabeza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1be94401f6a37d1a$::jsonb and revision=3) union all select 'ece:official:equipment:es:d12a1e5c8d86194c4729fcff' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d12a1e5c8d86194c4729fcff' and payload#>'{features}'=$verify_cb379d78a5d12f39$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tu puntuación de Fuerza es de 19 mientras lleves estos guanteletes. No tienen ningún efecto si tu Fuerza ya es de 19 o más.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_cb379d78a5d12f39$::jsonb and revision=3) union all select 'ece:official:equipment:es:d137ddfe32e465d25e312925' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d137ddfe32e465d25e312925' and payload#>'{features}'=$verify_35abc986f4488354$[{"id":"legacy-bonus-0","kind":"passive","name":"PassivePerception","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +5 a la Percepción Pasiva.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta vara posee una cabeza con reborde y las siguientes propiedades.\n\nAlerta. Mientras empuñes la vara, tendrás ventaja en las pruebas de Sabiduría (Percepción) y en las tiradas de iniciativa.\n\nConjuros. Mientras empuñes la vara, puedes utilizar una acción para lanzar uno de los siguientes conjuros desde ella: detectar el bien y el mal, detectar magia, detectar venenos y enfermedades o ver invisibilidad.\n\nAura protectora. Como acción, puedes clavar el extremo de la empuñadura en el suelo, tras lo cual la cabeza de la vara emitirá luz brillante en un radio de 18 m y luz tenue 18 m más allá. Siempre que tú y cualquier otra criatura que sea amistosa contigo os encontréis bajo la luz brillante, obtendréis un bonificador de +1 a la CA y a las tiradas de salvación. Además, podréis sentir la ubicación de cualquier criatura invisible hostil que también esté bajo la luz brillante.\n\nLa cabeza de la vara dejará de brillar y el efecto terminará después de 10 minutos o cuando una criatura utilice una acción para sacar la vara de suelo. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_35abc986f4488354$::jsonb and revision=3) union all select 'ece:official:equipment:es:d194c1925cd7eed15e88f9d2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d194c1925cd7eed15e88f9d2' and payload#>'{features}'=$verify_7b79f082bef1b2e7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Cuando falles una tirada de salvación de Destreza mientras lo lleves puesto, podrás utilizar tu reacción y gastar 1 de sus cargas para superar la tirada.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7b79f082bef1b2e7$::jsonb and revision=3) union all select 'ece:official:equipment:es:d2420446c122e6d1d1ade566' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d2420446c122e6d1d1ade566' and payload#>'{description}'=$verify_558a95cebcb036e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nFlecha · 1 po · 1 lb · 20 · 0.05 · 5\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_558a95cebcb036e3$::jsonb and payload#>'{rules,definition,description}'=$verify_1086a208ec8f4634$[{"id":"official-table","rows":[["Flecha","1 po","1 lb","20","0.05","5"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_1086a208ec8f4634$::jsonb and revision=3) union all select 'ece:official:equipment:es:d29807a264cc92b6ef5be271' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d29807a264cc92b6ef5be271' and payload#>'{features}'=$verify_32e18da2643e9df2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón tiene 10 cargas y recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, un enjambre de insectos engulle el bastón, lo destruye y luego se dispersa.\n\nConjuros. Mientras empuñes el bastón, podrás usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros: insecto gigante (4 cargas), plaga de insectos (5 cargas).\n\nNube de insectos. Mientras empuñes el bastón, podrás usar una acción y gastar 1 carga para hacer que un enjambre de insectos voladores inofensivos cubra un radio de 9 m a tu alrededor. Los insectos permanecerán durante 10 minutos y convertirán el área en una zona muy oscura para todas las criaturas menos para ti. El enjambre se mueve contigo y se mantiene centrado en ti. Un viento de al menos 15 km/h dispersará al enjambre y pondrá fin al efecto.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_32e18da2643e9df2$::jsonb and payload#>'{rules,personalDescription}'=$verify_a5dfa3d336a686cf$"Este bastón tiene 10 cargas y recupera 1d6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira 1d20. Con un 1, un enjambre de insectos consume y destruye el bastón, y luego se dispersa.\n\nConjuros. Mientras sostienes el bastón, puedes usar una acción para gastar algunas de sus cargas y lanzar uno de los siguientes conjuros desde él, usando la CD de tu salvación de conjuros: insecto gigante (4 cargas) o plaga de insectos (5 cargas).\n\nNube de insectos. Mientras sostienes el bastón, puedes usar una acción y gastar 1 carga para hacer que un enjambre de insectos voladores inofensivos se disperse en un radio de 30 pies a tu alrededor. Los insectos permanecen allí durante 10 minutos, lo que hace que el área quede muy oculta para las criaturas que no sean tú. El enjambre se mueve contigo y permanece centrado en ti. Un viento de al menos 10 millas por hora dispersa el enjambre y termina el efecto."$verify_a5dfa3d336a686cf$::jsonb and revision=3) union all select 'ece:official:equipment:es:d2a4db57f6b1c2d09cc9d4f6' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d2a4db57f6b1c2d09cc9d4f6' and payload#>'{features}'=$verify_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4ca76cc6ddf1af62$::jsonb and revision=3) union all select 'ece:official:equipment:es:d2c9cf7c7304dbd37f8bc7e1' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d2c9cf7c7304dbd37f8bc7e1' and payload#>'{features}'=$verify_dc07da072c2b7578$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, obtienes un bonificador de +2 a la CA contra ataques a distancia. Este bonificador se suma al bonificador a la CA normal del escudo. Además, cuando una criatura realice un ataque a distancia contra un objetivo que esté a 1,5 m o menos de ti, podrás usar tu reacción para convertirte en el objetivo del ataque.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dc07da072c2b7578$::jsonb and revision=3) union all select 'ece:official:equipment:es:d33208f224791802d5cc9023' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d33208f224791802d5cc9023' and payload#>'{description}'=$verify_fb0110dc01b844c7$"Objeto · Precio base · Peso\nMochila · 2 po · 5 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_fb0110dc01b844c7$::jsonb and payload#>'{rules,definition,description}'=$verify_467c0a803342b9d2$[{"id":"official-table","rows":[["Mochila","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_467c0a803342b9d2$::jsonb and revision=3) union all select 'ece:official:equipment:es:d3916bc71ae13afb7a224244' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d3916bc71ae13afb7a224244' and payload#>'{description}'=$verify_57ad9bd72f8bcb37$"Objeto · Precio base · Peso\nAntorcha · 1 pc · 1 lb\n\nAntorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_57ad9bd72f8bcb37$::jsonb and payload#>'{features}'=$verify_de7c9fd07470e6fa$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_de7c9fd07470e6fa$::jsonb and payload#>'{rules,definition,description}'=$verify_5a4b49e76e85ed57$[{"id":"official-table","rows":[["Antorcha","1 pc","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_5a4b49e76e85ed57$::jsonb and revision=3) union all select 'ece:official:equipment:es:d45091cecb894506094369a2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d45091cecb894506094369a2' and payload#>'{features}'=$verify_e1677d9db3bc1981$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bonificador de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica negra o azul oscura lleva bordadas pequeñas estrellas blancas o plateadas. Mientras la lleves puesta, recibirás un bonificador de +1 a las tiradas de salvación.\n\nSeis de las estrellas, situadas en la parte superior delantera de la túnica, son especialmente grandes. Mientras lleves puesta esta túnica, podrás utilizar una acción para arrancar una de las estrellas y usarla para lanzar proyectil mágico como un conjuro de nivel 5. Cada día al amanecer, 1d6 estrellas arrancadas reaparecerán en la túnica.\n\nMientras lleves puesta la túnica, podrás utilizar una acción para entrar en el Plano Astral junto con todo lo que vistas o lleves. Permanecerás allí hasta que utilices una acción para volver al plano en el que estabas. Reaparecerás en el último espacio que ocupabas o, si el espacio ya está ocupado, en el espacio sin ocupar más cercano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e1677d9db3bc1981$::jsonb and payload#>'{rules,personalDescription}'=$verify_9021e751c445f4d7$"Esta túnica de color negro o azul oscuro está bordada con pequeñas estrellas blancas o plateadas. Obtienes un bonificador de +l a la CA y a las tiradas de salvación mientras la lleves puesta.\n\nSeis de las estrellas, colocadas en la parte superior frontal de la túnica, son especialmente grandes. Siempre que vistas la túnica, puedes usar una acción para arrancar una de las estrellas y emplearla para lanzar proyectil mágico como con juro de nivel S. Cada día, al anochecer, reaparecerán ld6 de las estrellas arrancadas.\n\nAdemás, mientras lleves esta túnica podrás utilizar una acción para entrar en el Plano Astral, llevando contigo todo lo que portes o vistas. Permanecerás ahí hasta que uses una acción para volver al plano en el que estabas. Reaparecerás en el espacio que ocupabas antes o en el más cercano disponible si ese ya está ocupado."$verify_9021e751c445f4d7$::jsonb and revision=3) union all select 'ece:official:equipment:es:d557752500840d78b5e905d8' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d557752500840d78b5e905d8' and payload#>'{features}'=$verify_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dd50717b3781ab10$::jsonb and revision=3) union all select 'ece:official:equipment:es:d613ca81a782e29c124eff8f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d613ca81a782e29c124eff8f' and payload#>'{features}'=$verify_fbbab4029ece3564$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, podrás ver mucho mejor de lo normal hasta una distancia de 30 cm. Tendrás ventaja en las pruebas de Inteligencia (Investigación) que dependan de la vista si examinas una zona o estudias un objeto que se encuentre a esa distancia o menos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_fbbab4029ece3564$::jsonb and revision=3) union all select 'ece:official:equipment:es:d6f94e0376d1900f4c11bb8c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d6f94e0376d1900f4c11bb8c' and payload#>'{description}'=$verify_61b09f21613118e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nPincho de hierro · 1 po · 5 lb · 10 · 0.5 · 10\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_61b09f21613118e3$::jsonb and payload#>'{rules,definition,description}'=$verify_ca94dda6590b5857$[{"id":"official-table","rows":[["Pincho de hierro","1 po","5 lb","10","0.5","10"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_ca94dda6590b5857$::jsonb and revision=3) union all select 'ece:official:equipment:es:d81d22e38c3ddd4e620b5674' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d81d22e38c3ddd4e620b5674' and payload#>'{features}'=$verify_7a23c041d535fc2b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, recuperarás 1d6 puntos de golpe cada 10 minutos, siempre y cuando tengas al menos 1 punto de golpe. Si pierdes una parte del cuerpo, el anillo hace que te vuelva a crecer y recupere su funcionalidad completa tras 1d6 + 1 días si te mantienes con al menos 1 punto de golpe durante todo ese tiempo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7a23c041d535fc2b$::jsonb and revision=3) union all select 'ece:official:equipment:es:d837a9dc165434a7ebb4b2bb' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d837a9dc165434a7ebb4b2bb' and payload#>'{features}'=$verify_62756aacf630eddf$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas herraduras de hierro vienen de cuatro en cuatro. Mientras cuatro de ellas estén fijadas a los cascos de un caballo o de una criatura similar, le permitirán moverse con normalidad mientras flota 10 cm por encima del suelo. Este efecto implica que la criatura puede cruzar o permanecer sobre superficies no sólidas o inestables, como agua y lava. Además, no deja huellas e ignora el terreno difícil. Asimismo, la criatura podrá moverse a velocidad normal durante 12 horas al día, como máximo, sin padecer cansancio por hacer marchas forzadas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_62756aacf630eddf$::jsonb and revision=3) union all select 'ece:official:equipment:es:d853aa97a9cf8e6489371efd' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d853aa97a9cf8e6489371efd' and payload#>'{features}'=$verify_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ffeec24cc9187eb8$::jsonb and revision=3) union all select 'ece:official:equipment:es:d857ec4ef6d77131aa567d47' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d857ec4ef6d77131aa567d47' and payload#>'{features}'=$verify_3f71c7203bce29d4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras arda un fuego en este brasero de latón, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de fuego, como si hubieras lanzado conjurar elemental. El brasero no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl brasero pesa 2,5 kg.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3f71c7203bce29d4$::jsonb and revision=3) union all select 'ece:official:equipment:es:d8a3f2f409a708360ac1156f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d8a3f2f409a708360ac1156f' and payload#>'{features}'=$verify_ffc941d8b32c6a46$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nConjuros. Mientras empuñes la varita, podrás usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros (CD de salvación 17): inmovilizar monstruo (5 cargas) o inmovilizar persona (2 cargas).\n\nEscape asistido. Mientras empuñes la varita, podrás usar tu reacción para gastar 1 carga y obtener ventaja en una tirada de salvación que realices para evitar que te apresen o paralicen, o puedes emplear 1 carga para obtener ventaja en cualquier prueba que hagas para escapar de un agarre.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ffc941d8b32c6a46$::jsonb and payload#>'{rules,personalDescription}'=$verify_95b403dfe465d0ec$"Esta varita tiene 7 cargas para las siguientes propiedades. Recupera 1d6 + 1 cargas gastadas diariamente al amanecer. Si gastas la última carga de la varita, tira 1d20. Con un 1, la varita se deshace en cenizas y queda destruida.\n\nConjuros. Mientras sostienes la varita, puedes usar una acción para gastar algunas de sus cargas y lanzar uno de los siguientes conjuros (salvación CD 17): inmovilizar monstruo (5 cargas) o inmovilizar persona (2 cargas).\n\nEscape asistido. Mientras sostienes la varita, puedes usar tu reacción para gastar 1 carga y obtener ventaja en una tirada de salvación que realices para evitar ser paralizado o inmovilizado, o puedes gastar 1 carga y obtener ventaja en cualquier tirada que realices para escapar de un agarrón."$verify_95b403dfe465d0ec$::jsonb and revision=3) union all select 'ece:official:equipment:es:d915713ec2c391e5dcf80714' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d915713ec2c391e5dcf80714' and payload#>'{description}'=$verify_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_5615c435e74bef0a$::jsonb and payload#>'{features}'=$verify_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_6268396968fa5288$::jsonb and payload#>'{rules,definition,description}'=$verify_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_f8f536bb79fb87b3$::jsonb and revision=3) union all select 'ece:official:equipment:es:d9b601a829486f58d1edab2a' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d9b601a829486f58d1edab2a' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_765086698ac323cb$[{"id":"official-base-table","rows":[["Guja","20 po","6 lb","1d10 cortante","+0","Pesada, Gran alcance, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_765086698ac323cb$::jsonb and revision=3) union all select 'ece:official:equipment:es:d9e9a9a6ad6074aa856fdb75' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:d9e9a9a6ad6074aa856fdb75' and payload#>'{features}'=$verify_818805f0ac1beb2b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás ventaja en las tiradas de salvación contra cualquier conjuro que solo te haga objetivo a ti (no como parte de un área de efecto). Además, si sacas un 20 en la tirada de salvación y el conjuro es de nivel 7 o inferior, el conjuro no tendrá efecto alguno en ti y, en su lugar, hará objetivo al lanzador y utilizará el nivel del espacio de conjuro, la CD de salvación de conjuros, el bonificador de ataque y la aptitud mágica del lanzador.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_818805f0ac1beb2b$::jsonb and revision=3) union all select 'ece:official:equipment:es:da3415c797431ef012a27635' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:da3415c797431ef012a27635' and payload#>'{features}'=$verify_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$verify_49e3e80c25fd1c94$::jsonb and revision=3) union all select 'ece:official:equipment:es:daca2184e53f2ea25df94b05' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:daca2184e53f2ea25df94b05' and payload#>'{features}'=$verify_ad0db3441d684050$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este yelmo, podrás utilizar una acción para lanzar el conjuro detectar pensa- mientos (CD de salvación 13) desde él. Mientras mantengas la concentración en el conjuro, podrás usar una acción adicional para mandar un mensaje telepático a una criatura en la que te estés concen- trando. Podrá responderte usando una acción adicional mientras te concentres en ella.\n\nMientras te concentres en una criatura con detectar pensamientos, podrás utilizar una acción para lanzar el conjuro sugestión (CD de salvación 13) desde el yelmo sobre esa criatura. Una vez utilizada, la propiedad sugestión no puede volver a usarse hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ad0db3441d684050$::jsonb and revision=3) union all select 'ece:official:equipment:es:db68a706e3edbdffed736118' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:db68a706e3edbdffed736118' and payload#>'{features}'=$verify_7ee10a6b1ec9aba7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos guantes, nadar y escalar no te costará movimiento adicional y obtendrás un bonificador de +5 a las pruebas de Fuerza (Atletismo) que hagas para nadar o escalar.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7ee10a6b1ec9aba7$::jsonb and revision=3) union all select 'ece:official:equipment:es:db7d1b79dc665d3f57d5d2c2' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:db7d1b79dc665d3f57d5d2c2' and payload#>'{features}'=$verify_dde479bbe9eae2a6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta botella de latón pintado pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella. Al final de tu turno, el humo desaparece con un fogonazo inofensivo y un ifrit se manifestará en un espacio sin ocupar a 9 m o menos de ti.\n\nLa primera vez que se abra la botella, tu GM tirará para determina lo que ocurre.\n\n01–10 · El ifrit te ataca. Tras luchar durante 5 asaltos, el ifrit desaparecerá y la botella perderá su magia.\n11–90 · El ifrit te sirve durante 1 hora y hace lo que le ordenes. A continuación, regresará a la botella y un nuevo tapón le impedirá salir. El tapón no se puede quitar durante 24 horas. Las dos siguientes veces que se abra la botella, ocurrirá el mismo efecto. Si la botella se abre una cuarta vez, el ifrit se escapará y desaparecerá, y la botella perderá su magia.\n91–00 · El ifrit puede lanzar el conjuro deseo tres veces para ti. Desaparecerá cuando conceda el último deseo o después de 1 hora y la botella perderá su magia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dde479bbe9eae2a6$::jsonb and payload#>'{rules,personalDescription}'=$verify_f7a9d8024a460c2d$"Esta botella de latón pintado pesa 1 libra. Cuando usas una acción para quitar el tapón, una nube de humo espeso sale de ella. Al final de tu turno, el humo desaparece en un estallido inofensivo de fuego y en su lugar aparece un ifrit en un espacio libre a 30 pies o menos de ti. Su perfil se encuentra en el Monster Manual. La primera vez que se abra la botella, el DM tira para determinar qué pasa.\n\n01-10 - El ifri t te ataca. Después de luchar durante 5 asaltos, el ifrit desaparece y la botella pierde su magia.\n11-90 - El ifrit te sirve durante l hora, cumpliendo tu voluntad. Después vuelve a la botella, donde un nuevo tapón le contendrá. El tapón no puede ser retirado durante 24 horas. Las dos próximas veces que se abra la botella ocurre el mismo efecto. Si se abre una cuarta, el ifrit se escapa y desaparece, perdiendo la botella su magia.\n91-00 - El ifrit puede lanzar el conjuro deseo tres veces para ti. Desaparece cuando lanza el último de ellos o después de l hora, y la botella pierde su magia."$verify_f7a9d8024a460c2d$::jsonb and revision=3) union all select 'ece:official:equipment:es:db828358f6811c9a673a2d57' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:db828358f6811c9a673a2d57' and payload#>'{features}'=$verify_1c4fc0657463d9e9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El humo se filtra a través del tapón de plomo de esta botella de latón, que pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella y cubrirá un radio de 18 m. La zona que ocupa la nube estará muy oscura. Cada minuto que la botella permanezca abierta y dentro de la nube, el radio aumentará en 3 m hasta que alcance su máximo de 36 m.\n\nLa nube permanecerá mientras la botella esté abierta. Para cerrarla, tienes que utilizar una acción para pronunciar su palabra de activación. Una vez que se cierre la botella, la nube se disipará tras 10 minutos. Un viento moderado (de 15 a 30 km/h) también puede dispersar el humo en 1 minuto y un viento fuerte (más de 30 km/h) lo hará en 1 asalto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1c4fc0657463d9e9$::jsonb and revision=3) union all select 'ece:official:equipment:es:dbdd04e383a8cd140b7f0c66' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:dbdd04e383a8cd140b7f0c66' and payload#>'{features}'=$verify_39b77e31a352c43e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este aceite transparente y gelatinoso brilla debido a las minúsculas esquirlas de plata que contiene. Puede impregnar un arma cortante o perforante o hasta 5 unidades de munición cortante o perforante. Aplicar el aceite lleva 1 minuto. Durante 1 hora, el objeto impregnado es mágico y tiene un bonificador de +3 a las tiradas de ataque y de daño.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_39b77e31a352c43e$::jsonb and revision=3) union all select 'ece:official:equipment:es:dca7ce044bc3a61a7d7975a9' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:dca7ce044bc3a61a7d7975a9' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_e79cf78b61c71d5c$[{"id":"official-base-table","rows":[["Garrote grande","2 pp","10 lb","1d8 contundente","+0","A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_e79cf78b61c71d5c$::jsonb and revision=3) union all select 'ece:official:equipment:es:ddb03c90d649ff901a595dfd' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ddb03c90d649ff901a595dfd' and payload#>'{features}'=$verify_a5c1642dce15fd53$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, tendrás ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos, y los ataques de conjuro tendrán desventaja contra ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_a5c1642dce15fd53$::jsonb and revision=3) union all select 'ece:official:equipment:es:dfac5d1193ee8763411386fa' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:dfac5d1193ee8763411386fa' and payload#>'{features}'=$verify_7bc718f5417070c9$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cada uno de los tres compartimentos de esta aljaba está conectado con un espacio extradimensional, lo que le permite contener muchos objetos sin pesar nunca más de 1 kg. El compartimento más pequeño puede albergar hasta 60 flechas, virotes u objetos similares. El compartimento intermedio puede contener hasta 18 jabalinas u objetos parecidos. En el compartimento más grande caben hasta 6 objetos largos, como arcos, bastones o lanzas.\n\nPuedes extraer cualquier objeto que contenga esta aljaba igual que lo harías con una aljaba o vaina normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_7bc718f5417070c9$::jsonb and revision=3) union all select 'ece:official:equipment:es:dfe4f67404619490ab853e9d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:dfe4f67404619490ab853e9d' and payload#>'{features}'=$verify_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f0e511db536bffb9$::jsonb and revision=3) union all select 'ece:official:equipment:es:e14cde6c9aac3e864c054708' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e14cde6c9aac3e864c054708' and payload#>'{features}'=$verify_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$verify_098e651649ff7d4d$::jsonb and revision=4) union all select 'ece:official:equipment:es:e195a30cf2bed9617cab705d' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e195a30cf2bed9617cab705d' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_fceb5fda75291662$[{"id":"official-base-table","rows":[["Martillo ligero","2 po","2 lb","1d4 contundente","+0","Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_fceb5fda75291662$::jsonb and revision=3) union all select 'ece:official:equipment:es:e22d639500fbb1d59085b9a5' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e22d639500fbb1d59085b9a5' and payload#>'{features}'=$verify_9695271bece60149$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, tendrás ventaja en las tiradas de salvación contra conjuros.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9695271bece60149$::jsonb and revision=3) union all select 'ece:official:equipment:es:e2c6fc0f3a4001fca0154c52' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e2c6fc0f3a4001fca0154c52' and payload#>'{description}'=$verify_29de674beabfb97f$"Objeto · Precio base · Peso\nFuego de alquimista (frasco) · 50 po · 1 lb\n\nFuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_29de674beabfb97f$::jsonb and payload#>'{features}'=$verify_e827c91874ef8602$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_e827c91874ef8602$::jsonb and payload#>'{rules,definition,description}'=$verify_fc80bfec3e404bfa$[{"id":"official-table","rows":[["Fuego de alquimista (frasco)","50 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_fc80bfec3e404bfa$::jsonb and revision=3) union all select 'ece:official:equipment:es:e3acaffca731d7c31f0bfeff' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e3acaffca731d7c31f0bfeff' and payload#>'{features}'=$verify_12efb51145f6de93$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para colocar este cubo metálico de 2,5 cm de lado en el suelo y pronunciar su palabra de activación. El cubo se convertirá rápidamente en una fortaleza que permanecerá hasta que emplees una acción para pronunciar la palabra de activación que la hace desaparecer, que solo funcionará si la fortaleza está vacía.\n\nEsta fortificación es una torre cuadrada de 6 m de lado y 9 m de altura, con aspilleras en todos los lados y almenas en la parte superior. Su interior se divide en dos plantas conectadas mediante una escalera que recorre una de las paredes. La escalera termina en una trampilla que conduce al tejado. Cuando se activa, la torre tiene una puerta pequeña en el lado que mira hacia ti. La puerta se abre solo bajo tus órdenes, que puedes dar como acción adicional. Es inmune al conjuro abrir y otros efectos mágicos similares, como el de un carillón de apertura.\n\nTodas las criaturas situadas en la zona en la que aparezca la fortaleza deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 10d10 de daño contundente si la fallan o la mitad del daño si la superan. En ambos casos, cada criatura será empujada a un espacio sin ocupar junto a la fortaleza, pero fuera de ella. Los objetos situados en la zona y que no lleve o vista alguien sufrirán este daño y serán empujados automáticamente.\n\nLa torre está hecha de adamantina y su magia impide que la derriben. El tejado, la puerta y las paredes tienen 100 puntos de golpe cada uno, inmunidad al daño de armas no mágicas (salvo armas de asedio) y resistencia al resto de daño. Solo un conjuro deseo puede reparar la fortaleza (este uso cuenta como replicar un conjuro de nivel 8 o inferior). Cada vez que se lance deseo, el tejado, la puerta o una pared recuperará 50 puntos de golpe.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_12efb51145f6de93$::jsonb and revision=3) union all select 'ece:official:equipment:es:e59b07ec950530f903759662' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e59b07ec950530f903759662' and payload#>'{features}'=$verify_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bdb52a76377c1eea$::jsonb and revision=3) union all select 'ece:official:equipment:es:e6f279561dbf73cf66121000' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e6f279561dbf73cf66121000' and payload#>'{features}'=$verify_74bbd0eb847ed37e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesta esta capa, podrás utilizar una acción para pronunciar su palabra de activación. La capa se convertirá en unas alas de murciélago o de pájaro que se colocan a tu espalda durante 1 hora o hasta que repitas la palabra de activación como acción. Las alas te otorgan una velocidad volando de 18 m. Cuando desaparezcan, no podrás usarlas de nuevo durante 1d12 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_74bbd0eb847ed37e$::jsonb and revision=3) union all select 'ece:official:equipment:es:e6fb55a58513814680574185' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e6fb55a58513814680574185' and payload#>'{features}'=$verify_66537621eea405a8$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene indicaciones para influir y embelesar a los demás, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Carisma aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_66537621eea405a8$::jsonb and revision=3) union all select 'ece:official:equipment:es:e71f1a3639d0ca163bea1a3f' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e71f1a3639d0ca163bea1a3f' and payload#>'{features}'=$verify_d20dc719ee200707$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para lanzar el conjuro telaraña (CD de salvación 15) desde ella.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_d20dc719ee200707$::jsonb and revision=3) union all select 'ece:official:equipment:es:e994633540f2d0f6fe235b6b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e994633540f2d0f6fe235b6b' and payload#>'{features}'=$verify_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dd50717b3781ab10$::jsonb and revision=3) union all select 'ece:official:equipment:es:ea969a49b5350a175ac19b83' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ea969a49b5350a175ac19b83' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_36fbd84554054a1f$[{"id":"official-base-table","rows":[["Daga","2 po","1 lb","1d4 perforante","+0","Sutil, Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_36fbd84554054a1f$::jsonb and revision=3) union all select 'ece:official:equipment:es:eb25c4df5d5bd294667b7d08' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:eb25c4df5d5bd294667b7d08' and payload#>'{features}'=$verify_7f63cdf0190e902c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order"